mapper.select:
/* [업무·서식 연결] 분류 클래스와 연결 상태 - selectClassList */ SELECT S.WK_ID AS wkId, W.WK_NM AS wkNm, S.CLASS_SEQ AS classSeq, S.CLASS_NM AS classNm, S.DOC_TYP_CD AS docTypCd, L.LEFRM_ID AS lefrmId, L.LEFRM_NM AS lefrmNm, L.DOC_ID AS docId, S.LINK_YN AS linkYn FROM () S JOIN ocuoc_ocrwf_m W ON W.WK_ID = S.WK_ID LEFT JOIN ocuoc_lefrm_m L ON L.LEFRM_ID = S.MATCH_ID
S.WK_ID = #{wkId} AND S.MATCH_ID IS NULL
ORDER BY W.WK_NM, S.WK_ID, S.CLASS_SEQ

/* [업무·서식 연결] 문서 종류 코드 중복(KJB_ 유무만 달라도 같은 클래스에 맞으므로 중복) - countDocId */
SELECT COUNT(*)
  FROM ocuoc_lefrm_m
 WHERE (DOC_ID = #{docId} OR DOC_ID = 'KJB_' || #{docId} OR 'KJB_' || DOC_ID = #{docId})
AND LEFRM_ID != #{exceptLefrmId}

mapper.delete:
/* [업무·서식 연결] 서식의 연결 삭제 - deleteLinksOfForm */
DELETE FROM ocuoc_ocrwl_l
 WHERE LEFRM_ID = #{lefrmId}
   AND WK_ID IN (SELECT WK_ID FROM ocuoc_ocrwc_l)
